WITH bounded AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx,b.preClosePx,b.turnRatio,MAX(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS period_high FROM `newzl`.`hsj_stock_hq_basic` b WHERE b.bizdate>='2025-10-09') SELECT mktcode,tgtcode,bizdate FROM bounded WHERE bizdate='2026-04-14' AND lastPx/10000.0>=period_high AND ((lastPx-preClosePx)*100.0)/NULLIF(preClosePx,0)>6 AND turnRatio/10000.0>10;
